const reviewDimensions=[['quality','Product quality'],['accuracy','Order accuracy'],['value','Value for money'],['communication','Supplier communication'],['timeliness','Delivery / pickup timing']];
function validateReview(input){const reject=message=>{throw Object.assign(new Error(message),{status:400})};if(!Number.isInteger(input.rating)||input.rating<1||input.rating>5)reject('Choose a rating from 1 to 5.');const review={rating:input.rating};for(const [key]of reviewDimensions){const value=input[key];if(value===undefined||value===null||value==='')review[key]=null;else{if(!Number.isInteger(value)||value<1||value>5)reject('Optional ratings must be from 1 to 5.');review[key]=value}}for(const key of ['feedback','downsides']){const value=input[key]??'';if(typeof value!=='string'||value.length>1000)reject('Written feedback must be 1000 characters or fewer.');review[key]=value.trim()}if(![undefined,null,'','yes','no'].includes(input.recommend))reject('Choose a valid recommendation.');review.recommend=input.recommend||null;review.createdAt=new Date().toISOString();return review}
if(typeof module!=='undefined')module.exports={reviewDimensions,validateReview};
